let localVersion = '6.20261118.1';  //本地版本号

function getHosts() {
    return [
    'https://tingx.abrdns.com',
    'http://154.12.85.126:5000'
    ];
}

function getStvHosts() {
    return [
        'https://sangtacviet.com',
        'https://sangtacviet.app',
        'https://sangtacviet.vip',
        'https://sangtacviet.pro',
        'https://sangtacviet.xyz',
        'http://14.225.254.182',
        'http://103.82.20.93'
    ];
}

function getStvHost() {
    let c = getConfig.call(this);
    let saved = String(c.stv_host || '').trim();
    if (saved) return saved.replace(/\/+$/, '');
    return 'https://sangtacviet.com';
}

function setStvHost(host) {
    let list = getStvHosts();
    let target = String(host || '').replace(/\/+$/, '');
    if (list.indexOf(target) == -1) {
        return { ok: false, message: '未配置的STV线路：' + host };
    }
    setConfig.call(this, { stv_host: target });
    return { ok: true, host: target };
}

function stvNextHost() {
    let list = getStvHosts();
    let cur = getStvHost.call(this);
    let idx = list.indexOf(cur);
    let next = list[(idx + 1) % list.length];
    setConfig.call(this, { stv_host: next });
    return next;
}

function stvCurrentHostLabel() {
    let cur = getStvHost.call(this);
    let list = getStvHosts();
    let idx = list.indexOf(cur);
    return (idx >= 0 ? (idx + 1) + '/' + list.length + ' · ' : '') + cur;
}

function getHost() {
    let { source } = this;
    let c = getConfig.call(this);
    if (c.host) return String(c.host).replace(/\/+$/, '');
    let base = '';
    try { base = "https://tingx.abrdns.com"; } catch (e) {}
    if (!base && typeof baseUrl !== 'undefined' && baseUrl) base = String(baseUrl);
    if (!base) base = getHosts()[0];
    return base.replace(/\/+$/, '');
}

function getConfig() {
    let { source } = this;
    try {
        let configStr = source.getVariable();
        if (!configStr || configStr.trim() == "") return {};
        let config = JSON.parse(configStr);
        if (Array.isArray(config)) return config[0] || {};
        if (config && typeof config == 'object') return config;
        return {};
    } catch (e) { return {}; }
}

function setConfig(obj) {
    let { source } = this;
    try {
        let config = getConfig.call(this);
        for (let k in obj) { if (obj.hasOwnProperty(k)) config[k] = obj[k]; }
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) { return false; }
}

function ensureConfig() {
    let c = getConfig.call(this);
    let changed = false;
    if (!c.gender) { c.gender = 'boy'; changed = true; }
    if (c.source == undefined) { c.source = ''; changed = true; }
    if (!c.sources) { c.sources = { novel: [], audio: [], comic: [], video: [], download: [] }; changed = true; }
    if (changed) setConfig.call(this, c);
    return c;
}

function deviceType() {
    let { java } = this;
    try {
        var id = java.deviceID();
        if (id && id !== '') {
            return true;
        }
    } catch (e) {}

    try {
        var id = java.androidId();
        if (id && id !== '') {
            return false;
        }
    } catch (e) {}

    return false;
}

function getDeviceId() {
    let { java } = this;
    let dev = '';
    try { let id1 = java.deviceID(); if (id1 && String(id1) !== '') dev = String(id1); } catch (e) {}
    if (!dev) { try { let id2 = java.androidId(); if (id2 && String(id2) !== '') dev = String(id2); } catch (e) {} }
    return dev;
}

function checkMsg(res) {
    let { java } = this;
    try {
        let obj = JSON.parse(res);
        if (obj.code !== 0) {
            java.toast(obj.message);
        }
    } catch (e) {}
    return res;
}

function getToken() {
    let { source } = this;
    let b64 = '';
    try { b64 = String(source.getLoginHeader() || '').trim(); } catch (e) {}
    return { b64: b64 };
}

function buildHeaders() {
    let { java } = this;
    let t = getToken.call(this);
    let dev = getDeviceId.call(this);
    let ts = String(Math.floor(Date.now() / 1000));

    let plain = '';
    if (t.b64) {
        try { plain = java.base64Decode(t.b64); } catch (e) { plain = ''; }
    }

    return {
        'User-Agent': java.getWebViewUA(),
        'x-novel-token': t.b64,
        'x-novel-deviceid': dev,
        'x-novel-timestamap': ts,
        'x-novel-public': java.md5Encode(plain + dev + ts).toLowerCase(),
        'x-novel-version': '10'
    };
}

function postJson(path, obj) {
    let { java } = this;
    let headers = buildHeaders.call(this);
    headers['Content-Type'] = 'application/json';
    let opt = { method: 'POST', body: JSON.stringify(obj || {}), headers: headers };
    let res = java.ajax(getHost.call(this) + path + ',' + JSON.stringify(opt));
    res = decryptIfEncrypted.call(this, res);
    try { return JSON.parse(res); } catch (e) { return { code: -1, message: '解析失败', raw: res }; }
}

function getSourceList() {
    let list = [];
    try {
        let arr = postJson.call(this, '/api/source', {});
        if (Array.isArray(arr)) {
            arr.forEach(function (it) { if (it && it.enabled && it.name) list.push(it); });
            list.sort(function (a, b) { return (a.sort || 0) - (b.sort || 0); });
        }
    } catch (e) {}
    return list;
}

function getCmtBrowserOptions() {
    return {
        expandedCornersRadius: 20,
        dismissOnTouchOutside: true,
        isDraggable: true,
        shouldDimBackground: true,
        backgroundDimAmount: 0.5,
        hardwareAccelerated: true,
        isNestedScrollingEnabled: true,
        isGestureInsetBottomIgnored: true,
        setFitToContents: false,
        heightPercentage: 0.75,
        isHideable: true
    };
}

function showCmt(bid, cid, para, date, sourceName) {
    let { java } = this;
    let session = getSessionId.call(this) || getSessionIdFromCookie.call(this) || '';
    let url = getHost.call(this) + '/comment'
            + '?tab=paras&book_id=' + bid
            + '&item_id=' + cid
            + '&para=' + para
            + '&source=' + (sourceName || '')
            + '&session=' + session;
    try {
        java.showBrowser(url, null, 'window.java=java;', JSON.stringify(getCmtBrowserOptions.call(this)));
    } catch (e) {
        try { java.startBrowser(url, '段评'); } catch (e2) {
            java.toast('打开段评失败：' + e2);
        }
    }
}

function getSessionId() {
    let config = getConfig.call(this);
    return String(config.fanqie_sessionid || '');
}

function getSessionIdFromCookie() {
    const { cookie } = this;
    try {
        let cookieHeader = String(cookie.getCookie('fanqienovel.com'));
        let sessionId = cookieHeader.match(/sessionid=([^;]+)/)?.[1] || null;
        if (sessionId) return sessionId;
    } catch (e) {}
    return "";
}

function getJjToken() {
    let { source } = this;
    let config = getConfig.call(this);

    let loginInfoKey = '';
    try {
        let info = source.getLoginInfoMap() || {};
        loginInfoKey = String(info.get('晋江登录Token') || '').trim();
    } catch (e) {}

    if (loginInfoKey) return loginInfoKey;

    return String(config.jj_token || '').trim();
}

function buildJjHeaders() {
    let { java } = this;
    return {
        "source": "android",
        "versiontype": "reading",
        "versioncode": "467",
        "version-code": "467",
        "User-Agent": java.getWebViewUA()
    };
}

function jjEncode(data) {
    let { java } = this;
    return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", "KW8Dvm2N", "1ae2c94b").encryptBase64(data);
}

function isShelfSyncEnabled() {
    try {
        return String(getConfig.call(this).shelf_sync || 'off') == 'on';
    } catch (e) {
        return false;
    }
}

function syncShelf(isAdd) {
    let { java, book } = this;
    try {
        if (!book || !book.tocUrl) return;
        let raw = String(book.tocUrl || '').replace(/\\/g, '').replace(/^data:catalogUrl;base64,/, '');
        let idx = raw.indexOf(',');
        if (idx >= 0) raw = raw.substring(0, idx);
        raw = raw.replace(/[^A-Za-z0-9+/=]/g, '');
        let catalog = JSON.parse(String(java.base64Decode(raw) || '').replace(/\\/g, ''));
        let sourceName = String(catalog.source || '');
        let bookId = String(catalog.book_id || catalog.bookid || '');
        if (!bookId) return;

        let apiSource = '';
        let logins = '';
        if (sourceName.indexOf('番茄') >= 0) {
            apiSource = '番茄';
            logins = getSessionId.call(this) || getSessionIdFromCookie.call(this);
        } else if (sourceName.indexOf('晋江') >= 0) {
            apiSource = '晋江';
            logins = getJjToken.call(this);
        }
        if (!apiSource || !logins) {
            java.toast('书架同步：请先登录' + apiSource);
            return;
        }

        let res = postJson.call(this, '/api/bookshelf/sync', {
            source: apiSource,
            logins: String(logins),
            book_id: bookId,
            action: isAdd ? 'add' : 'del',
            group: ''
        });
        if (res && res.code == 0) {
            java.toast((isAdd ? '已同步到' : '已从') + apiSource + (isAdd ? '书架' : '书架移除'));
        } else {
            java.toast((res && res.message) || '书架同步失败');
        }
    } catch (e) {
        java.log('syncShelf error: ' + e);
        java.toast('书架同步失败');
    }
}

function syncProgress(chapterParams) {
    let { java } = this;
    try {
        let conf = getConfig.call(this);
        if ((conf.progress_sync || 'off') != 'on') return;

        let sourceName = String(chapterParams.source || '');
        let logins = '';
        if (/^晋江/.test(sourceName)) {
            logins = String(conf.jj_token || '');
        } else if (/^番茄/.test(sourceName)) {
            logins = String(conf.fanqie_sessionid || '');
        }
        if (!logins) return;

        let headers = buildHeaders.call(this);
        headers['Content-Type'] = 'application/json';

        let body = JSON.stringify({
            source: sourceName,
            book_id: String(chapterParams.book_id || ''),
            item_id: String(chapterParams.item_id || ''),
            logins: logins
        });

        let opt = { method: 'POST', body: body, headers: headers };
        let res = java.ajax(getHost.call(this) + '/api/progress,' + JSON.stringify(opt));
        res = decryptIfEncrypted.call(this, res);
        let obj = JSON.parse(res);
        if (obj.code !== 0) java.log('进度同步失败：' + (obj.message || '未知错误'));
    } catch (e) {
        java.log('进度同步异常：' + e);
    }
}

function decryptIfEncrypted(res) {
    let raw = String(res == undefined || res == null ? '' : res).trim();
    if (!raw) return res;

    if (raw.indexOf('"aes-256-gcm"') >= 0 && raw.charAt(0) == '{') {
        try {
            let obj = JSON.parse(raw);
            if (obj.alg == 'aes-256-gcm' && obj.data && obj.iv && obj.tag) {
                return aesGcmDecrypt.call(this, raw);
            }
            if (obj.data && typeof obj.data == 'object' && obj.data.alg == 'aes-256-gcm') {
                let dec = aesGcmDecrypt.call(this, obj.data);
                try { obj.data = JSON.parse(dec); }
                catch (e) { obj.data = dec; }
                return JSON.stringify(obj);
            }
        } catch (e) {}
    }
    return res;
}

function aesGcmDecrypt(payload) {
    let { java } = this;
    let obj = null;
    try {
        obj = (typeof payload == 'string') ? JSON.parse(payload) : payload;
        if (!obj || obj.alg !== 'aes-256-gcm' || !obj.data || !obj.iv || !obj.tag) return payload;
    } catch (e) { return payload; }

    try {
        let C = Packages.javax.crypto.Cipher;
        let K = Packages.javax.crypto.spec.SecretKeySpec;
        let G = Packages.javax.crypto.spec.GCMParameterSpec;
        let S = Packages.java.lang.String;
        let A = Packages.java.util.Arrays;
        let Sys = Packages.java.lang.System;

        let keyBytes = new S("Lk4#Fj9&Gh1*Ds6^Qw3!Er8@Ty5%Ui0o").getBytes("UTF-8");
