        let tagBytes = java.base64DecodeToByteArray(obj.tag);
        let dataBytes = java.base64DecodeToByteArray(obj.data);

        let combined = A.copyOf(dataBytes, dataBytes.length + tagBytes.length);
        Sys.arraycopy(tagBytes, 0, combined, dataBytes.length, tagBytes.length);

        let cipher = C.getInstance("AES/GCM/NoPadding");
        cipher.init(C.DECRYPT_MODE, new K(keyBytes, "AES"), new G(128, ivBytes));
        return new S(cipher.doFinal(combined), "UTF-8").toString();
    } catch (e) {}

    try {
        function b64dec(s) {
            let T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
            let out = [], v = 0, bits = 0;
            s = String(s).replace(/[^A-Za-z0-9+/]/g, '');
            for (let i = 0; i < s.length; i++) {
                v = (v << 6) | T.indexOf(s.charAt(i));
                bits += 6;
                if (bits >= 8) { bits -= 8; out.push((v >> bits) & 0xFF); }
            }
            return out;
