                else if (c < 0xF0) buf.push(((c & 0x0F) << 12) | ((plain[++i] & 0x3F) << 6) | (plain[++i] & 0x3F));
                else {
                    let cp = ((c & 0x07) << 18) | ((plain[++i] & 0x3F) << 12) | ((plain[++i] & 0x3F) << 6) | (plain[++i] & 0x3F);
                    cp -= 0x10000;
