            for (let i = 0; i < 8; i++) {
                if (b & 1) p ^= a;
                let hi = a & 0x80;
                a = (a << 1) & 0xFF;
                if (hi) a ^= 0x1b;
                b >>= 1;
            }
            return p;
        }
        function expandKey(key) {
            let Nk = 8, w = [], rcon = 1;
            for (let i = 0; i < Nk; i++) w.push([key[4*i], key[4*i+1], key[4*i+2], key[4*i+3]]);
            for (let i = Nk; i < 60; i++) {
                let t = w[i-1].slice();
                if (i % Nk == 0) {
                    t = [t[1], t[2], t[3], t[0]].map(x => SBOX[x]);
                    t[0] ^= rcon;
                    rcon = xtime(rcon);
                } else if (i % Nk == 4) {
                    t = t.map(x => SBOX[x]);
                }
                w.push([w[i-Nk][0]^t[0], w[i-Nk][1]^t[1], w[i-Nk][2]^t[2], w[i-Nk][3]^t[3]]);
            }
            let rk = [];
            for (let i = 0; i < w.length; i++) rk.push(w[i][0], w[i][1], w[i][2], w[i][3]);
