                if (round !== 14) {
                    for (let c = 0; c < 4; c++) {
                        let i = 4*c;
                        let a0 = st[i], a1 = st[i+1], a2 = st[i+2], a3 = st[i+3];
                        st[i]   = gmul(a0,2)^gmul(a1,3)^a2^a3;
                        st[i+1] = a0^gmul(a1,2)^gmul(a2,3)^a3;
                        st[i+2] = a0^a1^gmul(a2,2)^gmul(a3,3);
                        st[i+3] = gmul(a0,3)^a1^a2^gmul(a3,2);
                    }
                }
                for (let i = 0; i < 16; i++) st[i] ^= rk[round*16 + i];
            }
            return st;
        }
        function gfMul(x, y) {
            let z = new Array(16).fill(0);
            let v = y.slice();
            for (let i = 0; i < 128; i++) {
                if ((x[i >> 3] >> (7 - (i & 7))) & 1) {
                    for (let j = 0; j < 16; j++) z[j] ^= v[j];
                }
                let lsb = v[15] & 1;
                for (let j = 15; j > 0; j--) v[j] = ((v[j] >> 1) | ((v[j-1] & 1) << 7)) & 0xFF;
                v[0] >>= 1;
                if (lsb) v[0] ^= 0xE1;
            }
            return z;
        }
        function writeBitsBE(arr, offset, bits) {
            for (let i = 0; i < 8; i++) {
                arr[offset + 7 - i] = bits % 256;
                bits = Math.floor(bits / 256);
            }
        }
        function ghash(H, data, aadBits, ctBits) {
            let y = new Array(16).fill(0);
            for (let i = 0; i < data.length; i += 16) {
                let block = new Array(16).fill(0);
                for (let j = 0; j < 16 && i + j < data.length; j++) block[j] = data[i+j];
                for (let j = 0; j < 16; j++) y[j] ^= block[j];
                y = gfMul(y, H);
            }
            let lenBlock = new Array(16).fill(0);
            writeBitsBE(lenBlock, 0, aadBits);
            writeBitsBE(lenBlock, 8, ctBits);
            for (let j = 0; j < 16; j++) y[j] ^= lenBlock[j];
            y = gfMul(y, H);
            return y;
        }
        function inc32(block) {
            for (let i = 15; i >= 12; i--) {
                block[i] = (block[i] + 1) & 0xFF;
                if (block[i] !== 0) break;
            }
        }
