            (historyHtml ? '<div class="section" style="padding:0"><div class="history-head" onclick="toggleLogs()"><h2><i class="fas fa-history"></i> 历史更新 <span>' + historyCountText + '</span></h2><button class="toggle"><span id="toggleText">展开历史</span><i class="fas fa-chevron-down" id="toggleIcon"></i></button></div><div class="history-body" id="logList">' + historyHtml + '</div></div>' : '') +
            '<p class="foot">' + (force ? '本次为强制更新，请更新后再使用书源' : '更新后返回书源即可生效') + '</p>' +
            '</section></div>' +
