            'if(logsCollapsed){l.classList.remove("open");t.textContent="展开历史";i.className="fas fa-chevron-down";}else{l.classList.add("open");t.textContent="收起历史";i.className="fas fa-chevron-up";}}' +
            '</script></body></html>';

        if (downloadUrl) {
            try {
                java.startBrowserAwait('data:text/html;base64,' + java.base64Encode(bodyHtml), '书源更新', false);
            } catch (e) {
                java.toast('打开更新页失败：' + e);
            }
        } else {
            java.longToast('发现新版本：' + serverVer + '\n' + msg);
        }
        return;
    }

    if (cmp < 0) {
        java.longToast('非法版本\n本地版本：' + myLocalVer + '\n服务器版本：' + serverVer + '\n本地版本高于服务器版本，请检查书源来源是否被修改。');
        return;
    }
    java.toast('已是最新版本：' + myLocalVer);
}

function paraSettings() {
