        'body::before{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;' +
        'background:radial-gradient(900px 520px at 12% -8%,rgba(var(--primary-rgb),.16),transparent 68%),' +
        'radial-gradient(760px 480px at 94% 4%,rgba(120,220,230,.18),transparent 72%)}' +
        '.wrap{max-width:720px;margin:0 auto;position:relative;z-index:1}' +
        '.glass{background:linear-gradient(155deg,rgba(var(--surface-rgb),.86),rgba(var(--surface-rgb),.58));' +
        'border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:var(--shadow);' +
        'backdrop-filter:blur(22px) saturate(1.2);-webkit-backdrop-filter:blur(22px) saturate(1.2)}' +
        '.hero{display:flex;align-items:center;gap:14px;padding:17px 18px;margin-bottom:12px}' +
        '.hero-icon{flex:0 0 auto;width:46px;height:46px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:20px;' +
        'background:linear-gradient(135deg,var(--primary),var(--primary-dark));color:#fff}' +
        '.hero h1{margin:0;font-size:19px;line-height:1.25}' +
        '.hero p{margin:5px 0 0;font-size:12px;line-height:1.55;color:var(--muted)}' +
