        '<label class="switch"><input type="checkbox" id="stvSwitch" ' + (curStv == 'on' ? 'checked' : '') + '><span class="switch-slider"></span></label></div>' +
        '</section>' +

        '<div class="tip glass">当前：段评 <b id="curReview">' + (curReview == 'on' ? '开启' : '关闭') + '</b> · 图标 <b id="curStyle">' + curStyle + '</b> · 源阅适配 <b id="curSy">' + (curSy == 'on' ? '开启' : '关闭') + '</b>' +
        ' · 进度同步 <b id="curProgress">' + (curProgress == 'on' ? '开启' : '关闭') + '</b> · 书架同步 <b id="curShelf">' + (curShelf == 'on' ? '开启' : '关闭') + '</b>' +
