            return h;
        }

        var icons = {
            length: '<path d="M3 6h18M3 12h18M3 18h12"/>',
            status: '<polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>',
            sort: '<path d="M3 6h13M3 12h9M3 18h5"/><polyline points="17 10 21 14 17 18"/>'
        };

        var html = `<!DOCTYPE html>
