<title>番茄筛选</title>
<style>
:root{--bg:#0a0a0f;--text:#e8e8f0;--accent:#ff6b35;--accent-glow:rgba(255,107,53,.4);--gold:#f0c040}
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif;background:var(--bg);background-image:radial-gradient(ellipse at 30% 20%,#2a1205 0%,#0a0e27 50%,#1a0d1a 100%);color:var(--text);min-height:100vh;padding:20px;position:relative;overflow-x:hidden}
.stars{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:0}
.star{position:absolute;border-radius:50%;background:#fff;animation:twinkle var(--duration) ease-in-out infinite alternate;animation-delay:var(--delay)}
@keyframes twinkle{0%{opacity:.1;transform:scale(.8)}50%{opacity:.9;transform:scale(1.1)}100%{opacity:.2;transform:scale(.9)}}
.container{width:100%;max-width:640px;margin:0 auto;position:relative;z-index:10;background:rgba(15,12,20,.6);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-radius:24px;border:1px solid rgba(255,255,255,.08);box-shadow:0 20px 60px rgba(0,0,0,.6),0 0 60px rgba(255,107,53,.1);overflow:hidden;animation:cardIn .6s cubic-bezier(.22,.61,.36,1)}
@keyframes cardIn{from{opacity:0;transform:translateY(20px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}
.header{padding:28px 24px 20px;text-align:center;border-bottom:1px solid rgba(255,255,255,.06);background:linear-gradient(180deg,rgba(255,107,53,.12),transparent)}
.header-title{display:flex;align-items:center;justify-content:center;gap:10px}
.header-title svg{width:22px;height:22px;color:var(--accent);filter:drop-shadow(0 0 8px var(--accent-glow))}
.header h1{font-size:22px;font-weight:700;letter-spacing:1px;color:rgba(255,255,255,.95);text-shadow:0 0 24px rgba(255,107,53,.5)}
.header p{font-size:12px;color:rgba(255,255,255,.45);margin-top:6px;letter-spacing:2px}
.current-badge{display:flex;align-items:center;justify-content:center;gap:8px;margin:20px 24px 0;padding:12px 20px;background:rgba(255,107,53,.12);border:1px solid rgba(255,107,53,.3);border-radius:14px;font-size:13px;color:rgba(255,255,255,.7)}
.current-badge .dot{width:8px;height:8px;border-radius:50%;background:var(--accent);box-shadow:0 0 10px var(--accent-glow);animation:pulse 2s ease-in-out infinite}
@keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.6;transform:scale(1.2)}}
.current-badge strong{color:#fff;font-weight:600}
.section{padding:20px 24px 0}
.section:last-of-type{padding-bottom:0}
.section-title{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:600;color:rgba(255,255,255,.85);margin-bottom:12px;letter-spacing:.5px}
.section-title svg{width:16px;height:16px;color:var(--accent);filter:drop-shadow(0 0 6px var(--accent-glow))}
.tag{font-size:10px;padding:2px 8px;border-radius:10px;background:rgba(255,107,53,.15);border:1px solid rgba(255,107,53,.3);color:rgba(255,255,255,.6);font-weight:400;margin-left:auto}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.opt-card{position:relative;padding:12px 6px;border-radius:14px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08);cursor:pointer;transition:all .3s cubic-bezier(.22,.61,.36,1);text-align:center;overflow:hidden}
.opt-card:hover{border-color:rgba(255,255,255,.2);background:rgba(255,255,255,.06);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.3)}
.opt-card.selected{border-color:var(--accent);background:rgba(255,107,53,.18);box-shadow:0 0 20px rgba(255,107,53,.3)}
.opt-card.selected::after{content:'✓';position:absolute;top:5px;right:6px;width:16px;height:16px;border-radius:50%;background:var(--accent);color:#fff;font-size:10px;display:flex;align-items:center;justify-content:center;box-shadow:0 0 8px var(--accent-glow)}
.opt-name{font-size:12px;font-weight:500;color:rgba(255,255,255,.85);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:0 4px}
.opt-card.selected .opt-name{color:#fff}
.clear-area{padding:20px 24px 0}
.clear-btn{width:100%;padding:12px;border:1px dashed rgba(255,255,255,.25);border-radius:14px;background:transparent;font-size:13px;color:rgba(255,255,255,.5);cursor:pointer;transition:all .3s;display:flex;align-items:center;justify-content:center;gap:8px}
.clear-btn:hover{border-color:rgba(255,107,53,.6);color:var(--accent);background:rgba(255,107,53,.06)}
.clear-btn svg{width:14px;height:14px}
.footer{text-align:center;font-size:11px;color:rgba(255,255,255,.3);padding:16px 24px 22px;letter-spacing:1px;border-top:1px solid rgba(255,255,255,.05);margin-top:20px}
@media (max-width:480px){.grid{grid-template-columns:repeat(3,1fr);gap:8px}.header h1{font-size:20px}.section{padding:16px 16px 0}.clear-area{padding:16px 16px 0}}
</style>
