        s.style.setProperty('--delay', (Math.random() * 4) + 's');
        s.style.opacity = 0.2 + Math.random() * 0.6;
        if (size == 3) s.style.boxShadow = '0 0 6px rgba(255,255,255,0.5)';
        c.appendChild(s);
    }
})();
</script>
</body>
</html>`;

        var base64 = "data:text/html;base64," + java.base64Encode(html);
