        if (resultDivStart > -1) {
            var contentStart = body.indexOf('>', resultDivStart);
            if (contentStart > -1) {
                contentStart += 1;
                var contentEnd = body.indexOf('</div>', contentStart);
                if (contentEnd > contentStart) {
                    selectedItems = body.substring(contentStart, contentEnd).trim();
                    if (selectedItems == "未选择") {
                        selectedItems = "";
                    } else {
                        if (selectedItems.startsWith('">')) selectedItems = selectedItems.substring(2);
                        else if (selectedItems.startsWith('>')) selectedItems = selectedItems.substring(1);
                    }
                }
            }
        }

        setConfig.call(this, { fq_filter: selectedItems });

    if (selectedItems == "") {
        java.toast("已清除所有筛选条件");
    } else {
        java.toast("设置成功，仅番茄发现页生效\n当前：" + selectedItems);
    }
        } catch (e) {
            java.log(e);
            java.toast("已取消筛选设置");
    }
}

function encode(data) {
    let { java } = this;
    return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(data);
}

function decode(data) {
    let { java } = this;
    try {
        var encryptedBytes = java.base64DecodeToByteArray(data);
        var key = "F#kL9$mQpR2&sVzX";
        var iv = "7HnT3!cW8@xM0yBv";
        var crypto = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, iv);
        return crypto.decryptStr(encryptedBytes);
    } catch (e) {
        return data;
    }
}

function getStvCookie() {
    let c = getConfig.call(this);
    return String(c.stv_cookie || '').trim();
}

