function stvLogin(flag) {
    let { java, source } = this;
    let username = '', psw = '';
    try {
        if (flag == true) {
            username = result.get('STV账号') || '';
            psw = result.get('STV密码') || '';
        } else {
            let info = source.getLoginInfoMap() || {};
            username = info.get('STV账号') || '';
            psw = info.get('STV密码') || '';
        }
    } catch (e) {}

    username = String(username || '').trim();
    psw = String(psw || '').trim();
    if (!username || !psw) return java.toast('请填写STV账号和密码');

    let host = getStvHost.call(this);
    java.toast('正在登录STV…');
    try {
        let body = 'username=' + encodeURIComponent(username) + '&psw=' + encodeURIComponent(psw);
        let res = java.post(host + '/index.php?ajax=login', body, {
            'x-requested-with': 'com.sangtacviet.mobilereader',
            'User-Agent': java.getWebViewUA()
        });
        let respBody = String(res.body() || '');
        if (respBody.trim() != 'success') {
            return java.toast('STV登录失败：' + respBody);
        }
        let sets = [];
        try { sets = res.headers('set-cookie').toArray(); } catch (e) {}
        let cookieParts = [];
        for (let i = 0; i < sets.length; i++) {
            let kv = String(sets[i]).split(';')[0].trim();
            if (kv) cookieParts.push(kv);
        }
        let cookieStr = cookieParts.join('; ');
        if (!cookieStr) return java.toast('STV登录成功但未取到cookie');
        setConfig.call(this, { stv_cookie: cookieStr });
        java.toast('✅ STV登录成功\n线路：' + host + '\nCookie：' + cookieStr);
    } catch (e) {
        java.toast('STV登录异常：' + e);
    }
}

function stvLogout() {
    setConfig.call(this, { stv_cookie: '' });
    java.toast('已退出STV');
}

