@js:
function cleanText(t) {
    if (t == null) return '';
    return String(t)
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .replace(/[ \t]+\n/g, '\n')
        .replace(/\n{2,}/g, '\n')
        .replace(/^\n+|\n+$/g, '')
        .trim();
}

let chapterParams = JSON.parse(java.hexDecodeToString(result));
chapterParams.token = getJjToken();
chapterParams.version = localVersion;
let conf = getConfig.call(this);
let sourceName = chapterParams.source || '';

if (conf.chapter_refresh_force == 'on') {
    chapterParams.force_refresh = 'on';
}

if (conf.stv_content == 'on') {
    chapterParams.stv_content = 'on';
}

let toneVar = String(book.getVariable('custom') || '');
if (!toneVar) {
    if (sourceName == '番茄听书') toneVar = '1';
    else if (sourceName == '书旗听书') toneVar = 'yifei';
}
chapterParams.tone_id = toneVar;
syncProgress.call(this, chapterParams);

let paraOn = (conf.para_review || 'off') == 'on';
let paraStyle = conf.para_style || 'TEXT';
let syOn = (conf.para_sy || 'off') == 'on';

if (syOn) chapterParams.devicetype = "ios";
else chapterParams.devicetype = "android";

let paraSources = ['番茄小说', 'QQ阅读', '晋江', '半夏', '七猫', '少年梦', '书旗'];
if (paraOn && paraSources.indexOf(sourceName) != -1) {
    chapterParams.review = 'on';
    chapterParams.style = paraStyle;
}

if (sourceName == '书旗听书' || sourceName == '番茄听书') {
    let obj = postJson.call(this, '/api/audio', chapterParams);
    result = cleanText((obj.data || {}).main_url || '');
} else {
    let obj;
    try {
        obj = postJson.call(this, '/api/content', chapterParams);
    } catch (e) {
        obj = { code: -1, message: '', raw: '' };
    }

    if (shouldBlockByVersion.call(this, obj.data && obj.data.version)) {
        result = '';
    } else {
        let hasContent = !!(obj.data && obj.data.content != null && String(obj.data.content).trim() != '');
        let content = hasContent ? obj.data.content : '';
        let tab = (obj.data && obj.data.tab) || chapterParams.tab || '';
        let isVideoLink = (tab == 'video' && content && /^https?:\/\//i.test(String(content)));

        let rawText = hasContent ? String(content) : '';
        let cnCount = (rawText.match(/[\u4e00-\u9fa5]/g) || []).length;
        let valid = hasContent && cnCount >= 20;

        let stvOn = (conf.stv_content || 'off') == 'on';
        let stvSource = (sourceName == '晋江') ? 'jjwxc' : ((sourceName == '起点') ? 'qidian' : '');
        let needStv = !isVideoLink && !valid && stvOn && stvSource;

        if (needStv) {
            let urlIndex = chapterParams.item_id;
            let bookid = chapterParams.book_id;
            let h = stvSource;
            let bhost = getStvHost.call(this);
            let loginCookie = getStvCookie.call(this);

            if (!loginCookie) {
                result = '';
            } else {
                try {
                    let grantUrl = bhost + '/io/grantcontext/context?hostid=' + h + '&bookid=' + bookid;
                    let grantHeaders = {
                        'cookie': loginCookie,
                        'x-requested-with': 'com.sangtacviet.mobilereader'
                    };
                    let grantRes = java.get(grantUrl, grantHeaders);
                    let scriptCode = String(grantRes.body());

                    let sessionCookie = '';
                    try {
                        let sets = grantRes.headers('set-cookie').toArray();
                        let parts = [];
                        for (let si = 0; si < sets.length; si++) {
                            let kv = String(sets[si]).split(';')[0].trim();
                            if (kv) parts.push(kv);
                        }
                        sessionCookie = parts.join('; ');
                    } catch (e) {}

                    var __chapterKey = '';
                    var window = {
                        document: { hidden: false },
                        Capacitor: '0',
                        app: {
                            net: java,
                            reader: {
                                __defineGetter__: (k, func) => { __chapterKey = func(); }
                            }
                        }
                    };
                    var btoa = (s) => String(yuedu.base64Encode(s));
                    var Capacitor = {};
                    var key;
                    var yuedu = java;
                    var Pkgs = Packages;
                    Packages = undefined;
                    java = undefined;
                    eval('(()=>{var _0xp = globalThis.String.fromCharCode;String.fromCharCode = function() {var args = Array.prototype.slice.call(arguments);return _0xp.apply(null, args).replace(/const /g, "let ");};' + scriptCode + ';return key;})()');
                    java = yuedu;
                    Packages = Pkgs;
                    KEY = __chapterKey;

                    if (!KEY) {
                        result = '';
                    } else {
                        let allCookies = [loginCookie, sessionCookie].filter(Boolean).join('; ');
                        let stv_cookie = 'transmode=chinese; ' + allCookies;
                        let SIGN_SUFFIX = '&sajax=readchapter&erogh982^%*%^*';
                        let SIGN_KEY = KEY + SIGN_SUFFIX;
                        let sign = java.md5Encode('bookid=' + bookid + '&c=' + urlIndex + '&h=' + h + '&key=' + SIGN_KEY);
                        let chapterUrl = bhost + '/index.php?sajax=readchapter&h=' + h + '&bookid=' + bookid + '&c=' + urlIndex + '&key=' + KEY;

                        let chapterOpt = {
                            method: 'GET',
                            headers: {
                                'cookie': stv_cookie,
                                'X-STV-Sign': sign,
                                'x-requested-with': 'com.sangtacviet.mobilereader',
                                'x-stv-transport': 'app',
                                'Referer': bhost + '/',
                                'Origin': bhost
                            }
                        };
                        let stvRaw = '';
                        let retry = 0;
                        while (retry < 3) {
                            stvRaw = java.ajax(chapterUrl + ',' + JSON.stringify(chapterOpt)) + '';
                            if (stvRaw.indexOf('error code: 1015') == -1) break;
                            retry++;
                            if (retry < 3) {
                                try { java.lang.Thread.sleep(1000); } catch (e) {}
                            }
                        }
                        if (stvRaw.indexOf('error code: 1015') != -1) {
                            result = '';
                        } else {
                            try {
                                let jsonObj = JSON.parse(stvRaw);
                                if (jsonObj.data) {
                                    let text = String(jsonObj.data);

                                    text = text.replace(/<br\s*\/?>/gi, '\n');
                                    text = text.replace(/<\/p>/gi, '\n');
                                    text = text.replace(/<[^>]+>/g, '');

                                    text = text.replace(/^\uFEFF/, '');
                                    text = text.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
                                    text = text.replace(/[\u200B-\u200D\uFEFF]/g, '');

                                    text = text.replace(/&[^;]*?\([A-Za-z]{4,}\)[^;]*?;/g, '');
                                    text = text.replace(/<[^>]*?\([A-Za-z]{4,}\)[^>]*?>/g, '');
                                    text = text.replace(/\([A-Za-z]{4,}\)/g, '');

                                    text = text.replace(/<b><font color=red>[\s\S]*?<\/b>/gi, '');
                                    text = text.replace(/<!--[\s\S]*?-->/g, '');

                                    let lines = text.split('\n');
                                    let kept = [];
                                    for (let li = 0; li < lines.length; li++) {
                                        let line = lines[li];
                                        if (/^Người/.test(line)) continue;
                                        if (/@Bạn/.test(line)) continue;
                                        if (/Đọc tại/.test(line)) continue;
                                        if (/Tải.*Scan/.test(line)) continue;
                                        if (/[（(][^）)]*飞卢小说[^）)]*[）)]/.test(line)) continue;
                                        if (/看无下划线版小说请下载飞卢小说/.test(line)) continue;
                                        kept.push(line);
                                    }
                                    text = kept.join('\n');

                                    text = text.replace(/\n{2,}/g, '\n').trim();

                                    if (text) {
                                        if (h == 'jjwxc') {
                                            chapterParams.content = text;
                                            chapterParams.stv_content = stvOn ? 'on' : 'off';
                                            let obj2 = null;
                                            try {
                                                obj2 = postJson.call(this, '/api/content', chapterParams);
                                            } catch (e) {}
                                            if (paraOn && obj2 && obj2.data && obj2.data.content != null && String(obj2.data.content).trim() != '') {
                                                result = cleanText(obj2.data.content);
                                            } else {
                                                result = cleanText(text);
                                            }
                                        } else {
                                            result = cleanText(text);
                                        }
                                    } else {
                                        result = '';
                                    }
                                } else {
                                    result = '';
                                }
                            } catch (e) {
                                result = '';
                            }
                        }
                    }
                } catch (e) {
                    java = yuedu;
                    Packages = Pkgs;
                    result = '';
                }
            }
        } else if (isVideoLink) {
            if (book.durChapterIndex == chapter.index) {
                try {
                    java.startBrowser(String(content), chapter.title);
                    java.toast('正在加载视频\n视频加载较慢，请耐心等待');
                } catch (e) {}
            }
            result = '【刷新正文】播放\n直链:\n' + cleanText(content);
        } else {
            result = cleanText(content);
        }
    }
}

